{
  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C04"],
      "claim": "1-NA-PP1, a closely related amino-substituted fused heteroaromatic kinase inhibitor, reached high brain concentrations after systemic administration in mice, supporting CNS access for the query's similar aminopyrimidine/fused heteroaromatic core.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "MTX-241F, an aminopyrimidine-fused heteroaromatic with an N-aryl saturated heterocycle, achieved micromolar murine brain levels, directly supporting the query's morpholine/aminopyrimidine design.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "Compound 6, containing a morpholine sulfonamide and aminopyrimidine-like heteroaromatic, showed a brain/plasma ratio of 2.4 in rats, indicating high brain penetration despite polar heterocycles.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "Compound 40, an aminopyrimidine fused heteroaromatic with a lipophilic ether, had a brain/plasma AUC ratio of 2.2 and demonstrated brain target engagement after oral dosing, supporting adequate CNS exposure.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C09"],
      "claim": "SHP099, an aminopyrimidine with a basic amine and dichlorophenyl group, maintained brain/plasma ratios >1 after oral dosing, showing that similar heteroaromatic amines can achieve meaningful brain exposure.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Compound 8 had poor brain penetration (Bu/Pu 0.11), but it contains an aniline amide and CF3 motif absent in the query, making this negative result less transferable.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "Pass: multiple high-transfer direct CNS exposure measurements in closely related aminopyrimidine/fused heteroaromatic molecules (brain/plasma ratios >1, micromolar brain levels) outweigh the borderline TPSA/HBA physicochemical prior and the few poor-penetration analogues that contain additional amide/sulfonamide/CF3 liabilities absent in the query.",
  "evidence_gaps": [
    "No direct brain/plasma or CSF measurement for the exact query molecule.",
    "Efflux transporter status of the query is not experimentally determined.",
    "Human CNS pharmacokinetics are unknown.",
    "TPSA and HBA counts are borderline high and could still limit passive permeability in some contexts."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

